<script setup lang="ts">
import {computed,ref,onMounted,onBeforeUnmount,watch} from 'vue';import {createChart,type IChartApi,type ISeriesApi,type Time} from 'lightweight-charts';import type {Forecast} from '../../types';
const props=defineProps<{forecast:Forecast}>();const host=ref<HTMLDivElement>(),replay=ref(props.forecast.actualCandles?.length||0);let chart:IChartApi|undefined,actual:ISeriesApi<'Candlestick'>|undefined,predicted:ISeriesApi<'Candlestick'>|undefined,observer:ResizeObserver|undefined;
const context=computed(()=>props.forecast.inputCandles.slice(-60).map(c=>({time:c.time as Time,open:c.open,high:c.high,low:c.low,close:c.close})));
function draw(){if(!actual||!predicted)return;const rows=props.forecast.actualCandles||[];actual.setData([...context.value,...rows.slice(0,replay.value).map(c=>({...c,time:c.time as Time}))]);predicted.setData((props.forecast.predictedCandles||[]).map(c=>({...c,time:c.time as Time})));chart?.timeScale().fitContent();}
onMounted(()=>{if(!host.value)return;chart=createChart(host.value,{height:340,layout:{background:{color:'#0d1421'},textColor:'#8492a7'},grid:{vertLines:{color:'#1b2737'},horzLines:{color:'#1b2737'}},timeScale:{timeVisible:true}});actual=chart.addCandlestickSeries({upColor:'#00d997',downColor:'#ff5267',borderVisible:false,wickUpColor:'#00d997',wickDownColor:'#ff5267'});predicted=chart.addCandlestickSeries({upColor:'rgba(160,92,255,.42)',downColor:'rgba(210,82,150,.4)',borderUpColor:'#a05cff',borderDownColor:'#d25296',wickUpColor:'#a05cff',wickDownColor:'#d25296'});observer=new ResizeObserver(e=>chart?.applyOptions({width:e[0]?.contentRect.width||0}));observer.observe(host.value);draw();});
watch(()=>[props.forecast.actualCandles,props.forecast.predictedCandles,replay.value],draw);onBeforeUnmount(()=>{observer?.disconnect();chart?.remove();});
</script>
<template><div ref="host" class="comparison-chart"/><label class="replay-control">Phát lại nến thực <input v-model.number="replay" type="range" min="0" :max="forecast.actualCandles?.length||0"><span>{{replay}} / {{forecast.horizon}}</span></label></template>
